describe('Session Expired Message on Token Timeout', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should display session expired message when token times out', () => {
    // Intercept the initial API call
    cy.intercept('GET', '/api/user/profile').as('initialProfile');
    cy.wait('@initialProfile');

    // Simulate token expiration by intercepting subsequent calls and returning 411
    cy.intercept('GET', '/api/user/profile', {
      statusCode: 411,
      body: { error: 'Token expired' }
    }).as('expiredProfile');

    // Trigger an action that requires a valid token
    cy.get('[data-testid="refresh-button"]').click();

    // Wait for the expired API call
    cy.wait('@expiredProfile');

    // Verify session expired message is displayed
    cy.get('[data-testid="session-expired-message"]')
      .should('be.visible')
      .should('contain', 'Your session has expired');

    // Verify user is redirected to login page
    cy.url().should('include', '/login');

    // Verify logout button is visible
    cy.get('[data-testid="logout-button"]').should('be.visible');
  });

  it('should handle token timeout gracefully and redirect to login', () => {
    // Intercept the initial API call
    cy.intercept('GET', '/api/user/profile').as('initialProfile');
    cy.wait('@initialProfile');

    // Simulate token expiration with 411 status
    cy.intercept('GET', '/api/user/data', {
      statusCode: 411,
      body: { error: 'Token expired' }
    }).as('expiredData');

    // Trigger an action that requires a valid token
    cy.get('[data-testid="view-settings-button"]').click();

    // Wait for the expired API call
    cy.wait('@expiredData');

    // Verify session expired message is displayed
    cy.get('[data-testid="session-expired-message"]')
      .should('be.visible')
      .should('contain', 'Session expired');

    // Verify user is redirected to login page
    cy.url().should('include', '/login');

    // Verify login form elements are visible
    cy.get('[data-testid="email-input"]').should('be.visible');
    cy.get('[data-testid="password-input"]').should('be.visible');

    // Verify session expired message is not visible on login page
    cy.get('[data-testid="session-expired-message"]').should('not.exist');
  });
});
